    d=os.path.normpath(os.environ['RLM_SESSION_DIR']); t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps(g,conn4=True):
    H,W=len(g),len(g[0]); seen=set(); cl=[]
    for r in range(H):
        for c in range(W):
            if (r,c) in seen: continue
            col=g[r][c]; stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                a,b=stack.pop(); comp.append((a,b))
                dirs=((1,0),(-1,0),(0,1),(0,-1))
                if not conn4: dirs+=((1,1),(1,-1),(-1,1),(-1,-1))
                for da,db in dirs:
                    aa,bb=a+da,b+db
                    if 0<=aa<H and 0<=bb<W and (aa,bb) not in seen and g[aa][bb]==col:
                        seen.add((aa,bb)); stack.append((aa,bb))
            cl.append(comp)
    return cl
def f(g):
    H,W=len(g),len(g[0]); cnt=Counter(v for r in g for v in r); bg=cnt.most_common(1)[0][0]
    sgs=comps(g,conn4=False); shapes=[s for s in sgs if len(s)>1]; singles=[s[0] for s in sgs if len(s)==1]
    out=[[bg]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if (r,c) in set(singles):
                best=None;m=999
                for obj in shapes:
                    mind=min(abs(r-a)+abs(c-b) for a,b in obj)
                    if mind<m: m=mind;best=obj
                out[r][c]=bg if best is None else Counter(g[a][b] for a,b in best).most_common(1)[0][0]
            else:
                out[r][c]=g[r][c]
    return out
for k in ['Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4']:
    pred=f(G[k+' input']); exp=G[k+' output']
    print(k,'nbad:',sum(1 for r,p in enumerate(pred) for e in exp[r] if p!=e))

